        self.entries = {} if entries is None else entries
        self.namespace = namespace
        self.policy = 0

    def identity(self, name, revision):
        return (name, revision)

    def fetch(self, name, revision, values):
        key = (self.namespace, self.identity(name, revision))
        if key not in self.entries:
            self.entries[key] = sum(values)
        return self.entries[key]

